{v:'VER',what:'an elite crawler hanging on bites harder but slower: it does not down a full-health man with no armour in under 4 s',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__sim) return 'SKIP: no raid here';
   var bad=[], g, p, all, e, mh, i, fr=0, last, bites=[], downT=-1;
   try{
     __topClear(); __runPrep(); __resetCfg(); __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); p=g.player; if(!g||g.over) return 'SKIP: no live raid';
     all=g.ents.slice(); e=all.filter(function(x){ return x.kind==='crawler'&&x.hp>0; })[0];
     if(!e) return 'SKIP: no crawler on this map';
     g.ents=[e]; mh=p.maxhp; p.maxhp=100; p.hp=100; p.iv=0; p.armor=0; p.downed=false; p.stam=100;
     for(var k in keys) keys[k]=false;
     G.crouchTog=false; p.ads=false;
     if(typeof crawlerLatchBody!=='function') return 'SKIP: no latch on this build';
     e.elite=1; e.hp=e.maxhp=5000; e.x=p.x-(e.r+(p.r||11)+2); e.y=p.y; e.state='chase'; e.alert=2.4; e.tx=p.x; e.ty=p.y; e.cd=0;
     e.latchS=-1; e.latchBlk=0;
     last=p.hp;
     for(i=0;i<300;i++){
       __sim(1/60); fr++;
       if(p.hp<last-0.01) bites.push({t:fr/60,d:last-p.hp});
       last=p.hp;
       if(downT<0&&(p.downed||p.hp<=0)){ downT=fr/60; break; }
     }
     if(bites.length<3) return 'SKIP: the latched elite bit only '+bites.length+' times (staging)';
     if(bites[0].d<13*1.5) bad.push('the elite bite is no longer an elite bite ('+bites[0].d.toFixed(1)+')');
     if(downT>=0&&downT<4.0) bad.push('one latched elite downed a full-health man with no armour in '+downT.toFixed(2)+' s ('+bites.length+' bites at '+bites.map(function(b){ return b.t.toFixed(2); }).join(',')+')');
     if(downT<0&&bites.length<4) bad.push('in 5 s the latched elite bit only '+bites.length+' times');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{ for(var k2 in keys) keys[k2]=false; try{ if(all) g.ents=all; var g2=__state(); if(g2&&!g2.over){ g2.player.maxhp=mh||100; g2.player.hp=100; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); }
   return bad.length?bad.join('; '):null; }},
